import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProjectCard from './components/ProjectCard';
import AIAssistant from './components/AIAssistant';
import { PROJECTS, SKILLS } from './constants';
import { Project } from './types';
import { translations } from './translations';

const App: React.FC = () => {
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
  const [autoSlideEnabled, setAutoSlideEnabled] = useState(true);

  const t = translations[lang];

  // Reset media index and autoSlide when project changes
  useEffect(() => {
    setCurrentMediaIndex(0);
  }, [selectedProject]);

  const getMediaList = (project: Project) => {
    if (project.gallery && project.gallery.length > 0) return project.gallery;
    const list = [project.thumbnail];
    if (project.videoUrl) list.push(`VIDEO:${project.videoUrl}`);
    return list;
  };

  const handleNextMedia = (e?: React.MouseEvent, max?: number) => {
    if (e) e.stopPropagation();
    const limit = max || (selectedProject ? getMediaList(selectedProject).length : 0);
    if (limit > 1) {
      setCurrentMediaIndex((prev) => (prev + 1) % limit);
    }
  };

  const handlePrevMedia = (e: React.MouseEvent, max: number) => {
    e.stopPropagation();
    setCurrentMediaIndex((prev) => (prev - 1 + max) % max);
  };

  // Auto-slide effect
  useEffect(() => {
    let interval: number | undefined;

    if (selectedProject && autoSlideEnabled) {
      const mediaList = getMediaList(selectedProject);
      if (mediaList.length > 1) {
        interval = window.setInterval(() => {
          handleNextMedia(undefined, mediaList.length);
        }, 10000); // 10 seconds
      }
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [selectedProject, autoSlideEnabled, currentMediaIndex]);

  return (
    <div className="bg-[#050505] min-h-screen text-zinc-200 selection:bg-white selection:text-black">
      <Header lang={lang} setLang={setLang} />

      <main>
        <Hero lang={lang} />

        {/* Work Section */}
        <section id="work" className="py-32 px-6 max-w-7xl mx-auto">
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-20 gap-8">
            <div className="space-y-4">
              <span className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.4em]">{t.work.tagline}</span>
