const App: React.FC = () => {
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
  const [autoSlideEnabled, setAutoSlideEnabled] = useState(true);

  const t = translations[lang];

  // Reset media index and autoSlide when project changes
  useEffect(() => {
    setCurrentMediaIndex(0);
  }, [selectedProject]);

  const getMediaList = (project: Project) => {
    if (project.gallery && project.gallery.length > 0) return project.gallery;
    const list = [project.thumbnail];
    if (project.videoUrl) list.push(`VIDEO:${project.videoUrl}`);
    return list;
  };

  const handleNextMedia = (e?: React.MouseEvent, max?: number) => {
    if (e) e.stopPropagation();
    const limit = max || (selectedProject ? getMediaList(selectedProject).length : 0);
    if (limit > 1) {
      setCurrentMediaIndex((prev) => (prev + 1) % limit);
    }
  };

  const handlePrevMedia = (e: React.MouseEvent, max: number) => {
    e.stopPropagation();
    setCurrentMediaIndex((prev) => (prev - 1 + max) % max);
  };

  // Auto-slide effect
  useEffect(() => {
    let interval: number | undefined;

    if (selectedProject && autoSlideEnabled) {
      const mediaList = getMediaList(selectedProject);
      if (mediaList.length > 1) {
        interval = window.setInterval(() => {
          handleNextMedia(undefined, mediaList.length);
        }, 10000); // 10 seconds
      }
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [selectedProject, autoSlideEnabled, currentMediaIndex]);

  return (
    <div className="bg-[#050505] min-h-screen text-zinc-200 selection:bg-white selection:text-black">
      <Header lang={lang} setLang={setLang} />

      <main>
        <Hero lang={lang} />

        {/* Work Section */}
        <section id="work" className="py-32 px-6 max-w-7xl mx-auto">
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-20 gap-8">
            <div className="space-y-4">
              <span className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.4em]">{t.work.tagline}</span>
              <h2 className="text-6xl md:text-8xl font-serif">{t.work.title1} <span className="italic text-zinc-500">{t.work.title2}</span></h2>
            </div>
            <div className="text-zinc-500 max-w-sm text-sm leading-relaxed border-l border-zinc-800 pl-6">
              {t.work.desc}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-16">
            {PROJECTS.map(project => (
              <ProjectCard 
                key={project.id} 
                project={project} 
                onClick={(p) => setSelectedProject(p)} 
              />
            ))}
          </div>
        </section>

        {/* Skills Section */}
        <section id="about" className="py-32 bg-zinc-950 border-y border-zinc-900/50">
          <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 lg:grid-cols-2 gap-24 items-center">
            <div className="space-y-12">
              <div className="space-y-4">
                <span className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.4em]">{t.about.tagline}</span>
                <h2 className="text-5xl font-serif">{t.about.title1} <span className="italic text-zinc-500">{t.about.title2}</span>.</h2>
              </div>

              <p className="text-zinc-400 leading-relaxed text-lg font-light">
                {t.about.desc}
              </p>

              <div className="space-y-10">
                {SKILLS.map(skill => (
                  <div key={skill.name} className="group space-y-3">
                    <div className="flex justify-between items-center text-[10px] uppercase tracking-[0.2em] font-bold text-zinc-500 group-hover:text-white transition-colors">
                      <span className="flex items-center gap-3">
                        <span className="text-xl grayscale group-hover:grayscale-0 transition-all">{skill.icon}</span> {skill.name}
                      </span>
                      <span>{skill.level}%</span>
                    </div>
                    <div className="h-[1px] w-full bg-zinc-900">
                      <div 
                        className="h-full bg-white transition-all duration-1000 ease-in-out" 
                        style={{ width: `${skill.level}%` }}
                      ></div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="relative">
              <div className="absolute -inset-4 border border-zinc-800 rounded-sm"></div>
              <img 
                src="https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&q=80&w=1000" 
                alt="Workspace" 
                className="relative w-full aspect-[4/5] object-cover grayscale brightness-50 hover:grayscale-0 hover:brightness-100 transition-all duration-1000"
              />
            </div>
          </div>
        </section>

        {/* Contact Section */}
        <section id="contact" className="py-40 px-6 text-center bg-black relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_50%_-20%,rgba(255,255,255,0.05)_0%,transparent_50%)] pointer-events-none"></div>
          <div className="relative z-10 max-w-4xl mx-auto space-y-16">
            <h2 className="text-6xl md:text-9xl font-serif leading-none">{t.contact.title1} <br /> <span className="italic text-zinc-500">{t.contact.title2}</span></h2>
            <p className="text-zinc-500 text-xl font-light max-w-2xl mx-auto">{t.contact.desc}</p>

            <div className="flex flex-col items-center gap-8">
              <a href="mailto:hello@alexthorne.3d" className="text-3xl md:text-5xl font-bold tracking-tighter hover:text-zinc-400 transition-all border-b border-zinc-800 pb-4">
                hello@alexthorne.3d
              </a>
              <div className="flex gap-10 text-[10px] uppercase tracking-[0.3em] font-bold text-zinc-500">
                <a href="#" className="hover:text-white transition-colors">ArtStation</a>
                <a href="#" className="hover:text-white transition-colors">LinkedIn</a>
                <a href="#" className="hover:text-white transition-colors">Instagram</a>
              </div>
            </div>
          </div>
        </section>
      </main>

      <footer className="py-12 border-t border-zinc-900 px-6 bg-black">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6 text-[9px] uppercase tracking-[0.4em] font-bold text-zinc-700">
          <p>© 2024 Alex Thorne — Digital Artist & Animator</p>
          <p>{t.contact.footer}</p>
        </div>
      </footer>

      {/* Project Modal */}
      {selectedProject && (() => {
        const mediaList = getMediaList(selectedProject);

        return (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 md:p-10 bg-black/98 backdrop-blur-2xl animate-in fade-in duration-500">
            <div className="relative max-w-6xl w-full bg-black border border-zinc-900 h-full md:h-auto md:max-h-[90vh] overflow-y-auto rounded-sm shadow-2xl">
              <button 
                onClick={() => setSelectedProject(null)}
                className="fixed md:absolute top-6 right-6 z-[70] w-12 h-12 bg-white text-black rounded-full flex items-center justify-center hover:scale-110 transition-all shadow-xl"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>

              <div className="p-6 md:p-16 space-y-12">
                <div className="space-y-4">
                  <div className="flex items-center gap-4 text-zinc-500 uppercase tracking-[0.2em] text-[10px] font-bold">
                    <span>{selectedProject.category}</span>
                    <span className="w-1 h-1 bg-zinc-800 rounded-full"></span>
                    <span>{selectedProject.year}</span>
                  </div>
                  <h2 className="text-4xl md:text-7xl font-serif">{selectedProject.title}</h2>
                </div>

                {/* Carousel Container con deslizamiento lateral */}
                <div className="relative w-full aspect-video bg-zinc-950 rounded-sm overflow-hidden group shadow-2xl border border-zinc-900">
                  <div 
                    className="w-full h-full flex transition-transform duration-[1000ms] ease-[cubic-bezier(0.65,0,0.35,1)]"
                    style={{ transform: `translateX(-${currentMediaIndex * 100}%)` }}
                  >
                    {mediaList.map((item, idx) => {
                      const isItemVideo = item.startsWith('VIDEO:');
                      const url = isItemVideo ? item.replace('VIDEO:', '') : item;

                      return (
                        <div key={idx} className="w-full h-full flex-shrink-0 relative overflow-hidden flex items-center justify-center bg-black">
                          {isItemVideo ? (
                            <iframe 
                              src={`${url}${url.includes('?') ? '&' : '?'}autoplay=1&mute=1`}
                              className="absolute inset-0 w-full h-full object-cover"
                              frameBorder="0"
                              allow="autoplay; fullscreen; picture-in-picture"
                              allowFullScreen
                              title={`${selectedProject.title}-${idx}`}
                              style={{ border: 'none' }}
                            ></iframe>
                          ) : (
                            <img 
                              src={url} 
                              alt={`${selectedProject.title}-${idx}`} 
                              className="w-full h-full object-cover" 
                            />
                          )}
                        </div>
                      );
                    })}
                  </div>

                  {/* Auto-slide toggle - Icono minimalista */}
                  {mediaList.length > 1 && (
                    <button 
                      onClick={() => setAutoSlideEnabled(!autoSlideEnabled)}
                      className="absolute top-6 left-6 z-20 w-10 h-10 bg-black/40 backdrop-blur-md flex items-center justify-center rounded-full border border-white/5 hover:bg-black/60 hover:border-white/20 transition-all text-white"
                      title={autoSlideEnabled ? 'Disable Auto-play' : 'Enable Auto-play'}
                    >
                      {autoSlideEnabled ? (
                        <svg className="w-4 h-4" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16" /><rect x="14" y="4" width="4" height="16" /></svg>
                      ) : (
                        <svg className="w-4 h-4 ml-0.5" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z" /></svg>
                      )}
                    </button>
                  )}

                  {/* Navigation Controls */}
                  {mediaList.length > 1 && (
                    <>
                      <button 
                        onClick={(e) => handlePrevMedia(e, mediaList.length)}
                        className="absolute left-6 top-1/2 -translate-y-1/2 w-14 h-14 bg-black/30 hover:bg-white hover:text-black rounded-full flex items-center justify-center transition-all opacity-0 group-hover:opacity-100 backdrop-blur-sm border border-white/10"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                      </button>
                      <button 
                        onClick={(e) => handleNextMedia(e, mediaList.length)}
                        className="absolute right-6 top-1/2 -translate-y-1/2 w-14 h-14 bg-black/30 hover:bg-white hover:text-black rounded-full flex items-center justify-center transition-all opacity-0 group-hover:opacity-100 backdrop-blur-sm border border-white/10"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                      </button>

                      {/* Indicators */}
                      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex gap-4 z-10 items-center">
                        {mediaList.map((_, idx) => (
                          <button 
                            key={idx}
                            onClick={() => setCurrentMediaIndex(idx)}
                            className="group p-2"
                          >
                            <div className={`h-[2px] transition-all duration-700 rounded-full ${idx === currentMediaIndex ? 'w-10 bg-white' : 'w-4 bg-white/20 group-hover:bg-white/40'}`} />
                          </button>
                        ))}
                      </div>
                    </>
                  )}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-16 pb-10">
                  <div className="lg:col-span-2 space-y-8">
                    <div className="space-y-4">
                      <h3 className="text-xs font-bold uppercase tracking-widest text-zinc-600">{t.project.overview}</h3>
                      <p className="text-lg md:text-2xl text-zinc-300 leading-relaxed font-light">{selectedProject.description}</p>
                    </div>
                  </div>

                  <div className="space-y-10">
                    <div className="space-y-4">
                      <h3 className="text-xs font-bold uppercase tracking-widest text-zinc-600">{t.project.pipeline}</h3>
                      <div className="flex flex-wrap gap-2">
                        {selectedProject.tools.map(tool => (
                          <span key={tool} className="px-4 py-2 bg-zinc-900/50 border border-zinc-800 text-[10px] uppercase tracking-widest text-zinc-400 font-bold rounded-full">
                            {tool}
                          </span>
                        ))}
                      </div>
                    </div>

                    <div className="pt-6 border-t border-zinc-900">
                      <p className="text-zinc-600 text-[10px] uppercase tracking-widest leading-loose">
                        {t.project.aiNote}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      })()}

      <AIAssistant lang={lang} />
    </div>
  );
};

export default App;

