    let interval: number | undefined;
    if (selectedProject && autoSlideEnabled) {
      const mediaList = getMediaList(selectedProject);
      if (mediaList.length > 1) {
        interval = window.setInterval(() => {
          handleNextMedia(undefined, mediaList.length);
