            <p className="text-zinc-500 text-xl font-light max-w-2xl mx-auto">{t.contact.desc}</p>

            <div className="flex flex-col items-center gap-8">
              <a href="mailto:hello@matias.cgi" className="text-3xl md:text-5xl font-bold tracking-tighter hover:text-white transition-all border-b border-zinc-800 pb-4 text-zinc-300">
                hello@matias.cgi
