import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProjectCard from './components/ProjectCard';
import AIAssistant from './components/AIAssistant';
import { PROJECTS, SKILLS } from './constants';
import { Project } from './types';
import { translations } from './translations';

const App: React.FC = () => {
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
  const [autoSlideEnabled, setAutoSlideEnabled] = useState(true);
  const [activeFilter, setActiveFilter] = useState<'All' | 'Animation' | 'Lookdev' | 'Environment'>('All');

  const t = translations[lang];

  // Lock body scroll when modal is open
  useEffect(() => {
    if (selectedProject) {
      document.body.classList.add('modal-open');
    } else {
      document.body.classList.remove('modal-open');
    }
    setCurrentMediaIndex(0);
  }, [selectedProject]);

  const getMediaList = (project: Project) => {
    if (project.gallery && project.gallery.length > 0) return project.gallery;
    const list = [project.thumbnail];
    if (project.videoUrl) list.push(`VIDEO:${project.videoUrl}`);
    return list;
  };

  const handleNextMedia = (e?: React.MouseEvent, max?: number) => {
    if (e) e.stopPropagation();
    const limit = max || (selectedProject ? getMediaList(selectedProject).length : 0);
    if (limit > 1) {
      setCurrentMediaIndex((prev) => (prev + 1) % limit);
    }
  };

  const handlePrevMedia = (e: React.MouseEvent, max: number) => {
    e.stopPropagation();
    setCurrentMediaIndex((prev) => (prev - 1 + max) % max);
  };

  useEffect(() => {
    let interval: number | undefined;
    if (selectedProject && autoSlideEnabled) {
      const mediaList = getMediaList(selectedProject);
      if (mediaList.length > 1) {
        interval = window.setInterval(() => {
          handleNextMedia(undefined, mediaList.length);
        }, 8000); 
      }
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [selectedProject, autoSlideEnabled, currentMediaIndex]);

  const filteredProjects = PROJECTS.filter(project => {
    if (activeFilter === 'All') return true;
    if (activeFilter === 'Animation') return project.category.includes('Animación') || project.category.includes('Animation');
    if (activeFilter === 'Lookdev') return project.category.includes('Lookdev');
    if (activeFilter === 'Environment') return project.category.includes('Environment') || project.category.includes('Entorno');
    return true;
  });

  return (
    <div className="bg-[#050505] min-h-screen text-zinc-200 selection:bg-white selection:text-black">
      <Header lang={lang} setLang={setLang} />

      <main>
        <Hero lang={lang} />

        <section id="work" className="py-40 px-6 max-w-7xl mx-auto">
          <div className="flex flex-col md:flex-row md:items-end justify-between mb-24 gap-12">
            <div className="space-y-6">
              <span className="text-zinc-600 text-[10px] font-black uppercase tracking-[0.5em]">{t.work.tagline}</span>
              <h2 className="text-7xl md:text-9xl font-serif text-white tracking-tighter leading-none">{t.work.title1} <br /><span className="italic text-zinc-500">{t.work.title2}</span></h2>
            </div>
            <div className="text-zinc-500 max-w-sm text-sm leading-relaxed border-l border-zinc-800 pl-8 font-light italic">
              {t.work.desc}
            </div>
          </div>

          {/* Filtros de Proyectos */}
          <div className="flex flex-wrap gap-4 mb-20">
            {[
              { id: 'All', label: t.work.filterAll },
              { id: 'Animation', label: t.work.filterAnim },
              { id: 'Lookdev', label: t.work.filterLook },
              { id: 'Environment', label: t.work.filterEnv }
            ].map(filter => (
              <button
                key={filter.id}
                onClick={() => setActiveFilter(filter.id as any)}
                className={`px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all duration-500 border ${
                  activeFilter === filter.id 
                    ? 'bg-white text-black border-white shadow-[0_0_20px_rgba(255,255,255,0.2)]' 
                    : 'bg-transparent text-zinc-600 border-zinc-900 hover:border-zinc-500 hover:text-zinc-300'
                }`}
              >
                {filter.label}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-20 transition-all duration-500">
            {filteredProjects.map(project => (
              <ProjectCard 
                key={project.id} 
                project={project} 
                onClick={(p) => setSelectedProject(p)} 
              />
            ))}
          </div>
        </section>

        <section id="about" className="py-40 bg-zinc-950/50 border-y border-zinc-900/30">
          <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 lg:grid-cols-2 gap-32 items-center">
            <div className="space-y-16">
              <div className="space-y-6">
                <span className="text-zinc-600 text-[10px] font-black uppercase tracking-[0.5em]">{t.about.tagline}</span>
                <h2 className="text-6xl font-serif text-white tracking-tighter leading-none">{t.about.title1} <span className="italic text-zinc-500">{t.about.title2}</span>.</h2>
              </div>

              <p className="text-zinc-400 leading-relaxed text-xl font-light">
                {t.about.desc}
              </p>

              <div className="space-y-12">
                {SKILLS.map(skill => (
                  <div key={skill.name} className="group space-y-4">
                    <div className="flex justify-between items-center text-[10px] uppercase tracking-[0.3em] font-black text-zinc-500 group-hover:text-white transition-all">
                      <span className="flex items-center gap-4">
                        <span className="text-2xl group-hover:scale-125 transition-transform duration-500 grayscale group-hover:grayscale-0">{skill.icon}</span> {skill.name}
                      </span>
                      <span className="font-mono">{skill.level}%</span>
                    </div>
                    <div className="h-px w-full bg-zinc-900 overflow-hidden">
                      <div 
                        className="h-full bg-gradient-to-r from-zinc-700 to-white transition-all duration-[1500ms] ease-in-out" 
                        style={{ width: `${skill.level}%` }}
                      ></div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="relative group">
              <div className="absolute -inset-6 border border-zinc-800/50 rounded-sm scale-95 group-hover:scale-100 transition-transform duration-1000"></div>
              <img 
                src="https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&q=80&w=1000" 
                alt="Workspace" 
                className="relative w-full aspect-[4/5] object-cover rounded-sm shadow-2xl transition-all duration-1000 group-hover:brightness-110"
              />
            </div>
          </div>
        </section>

        <section id="contact" className="py-60 px-6 text-center bg-black relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_50%_-20%,rgba(255,255,255,0.08)_0%,transparent_60%)] pointer-events-none"></div>
          <div className="relative z-10 max-w-5xl mx-auto space-y-24">
            <h2 className="text-7xl md:text-[10rem] font-serif leading-none text-white tracking-tighter">{t.contact.title1} <br /> <span className="italic text-zinc-600">{t.contact.title2}</span></h2>
            <p className="text-zinc-500 text-2xl font-light max-w-2xl mx-auto italic">{t.contact.desc}</p>

            <div className="flex flex-col items-center gap-12">
              <a href="mailto:hello@matias.cgi" className="text-4xl md:text-7xl font-bold tracking-tighter hover:text-white transition-all border-b border-zinc-900 hover:border-white pb-6 text-zinc-400">
                hello@matias.cgi
              </a>
              <div className="flex gap-12 text-[11px] uppercase tracking-[0.4em] font-black text-zinc-600">
                <a href="#" className="hover:text-white transition-all hover:scale-110">ArtStation</a>
                <a href="#" className="hover:text-white transition-all hover:scale-110">LinkedIn</a>
                <a href="#" className="hover:text-white transition-all hover:scale-110">Instagram</a>
              </div>
            </div>
          </div>
        </section>
      </main>

      <footer className="py-16 border-t border-zinc-900 px-6 bg-black">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8 text-[10px] uppercase tracking-[0.5em] font-black text-zinc-800">
          <p className="hover:text-zinc-500 transition-colors">© 2024 Matías Navarrete — Digital Artist & Animator (matias cgi)</p>
          <p className="text-zinc-900">{t.contact.footer}</p>
        </div>
      </footer>

      {/* Modal de Proyecto */}
      {selectedProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-8 bg-black/95 backdrop-blur-3xl animate-in fade-in duration-500">
          <div className="relative max-w-7xl w-full bg-[#050505] border border-zinc-900 h-full md:h-auto md:max-h-[95vh] overflow-y-auto rounded-sm shadow-[0_0_100px_rgba(0,0,0,1)]">
            <button 
              onClick={() => setSelectedProject(null)}
              className="fixed md:absolute top-8 right-8 z-[110] w-14 h-14 bg-white text-black rounded-full flex items-center justify-center hover:scale-110 active:scale-90 transition-all shadow-2xl group"
            >
              <svg className="w-8 h-8 group-hover:rotate-90 transition-transform duration-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>

            <div className="p-8 md:p-20 space-y-16">
              <div className="space-y-6">
                <div className="flex items-center gap-6 text-zinc-500 uppercase tracking-[0.4em] text-[11px] font-black">
                  <span>{selectedProject.category}</span>
                  <span className="w-2 h-[1px] bg-zinc-800"></span>
                  <span>{selectedProject.year}</span>
                </div>
                <h2 className="text-5xl md:text-8xl font-serif text-white tracking-tighter">{selectedProject.title}</h2>
              </div>

              <div className="relative w-full aspect-video min-h-[60vh] bg-black rounded-sm overflow-hidden group shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-zinc-900/50">
                <div 
                  className="w-full h-full flex transition-transform duration-[1200ms] ease-[cubic-bezier(0.77,0,0.175,1)]"
                  style={{ transform: `translateX(-${currentMediaIndex * 100}%)` }}
                >
                  {getMediaList(selectedProject).map((item, idx) => {
                    const isItemVideo = item.startsWith('VIDEO:');
                    const url = isItemVideo ? item.replace('VIDEO:', '') : item;

                    return (
                      <div key={idx} className="w-full h-full min-w-full flex-shrink-0 relative overflow-hidden bg-black flex items-center justify-center">
                        {isItemVideo ? (
                          <iframe 
                            src={`${url}${url.includes('?') ? '&' : '?'}autoplay=1&mute=1&loop=1`}
                            className="absolute inset-0 w-full h-full object-cover scale-[1.01]"
                            frameBorder="0"
                            allow="autoplay; fullscreen; picture-in-picture"
                            allowFullScreen
                            title={`${selectedProject.title}-${idx}`}
                            style={{ border: 'none' }}
                          ></iframe>
                        ) : (
                          <img 
                            src={url} 
                            alt={`${selectedProject.title}-${idx}`} 
                            className="absolute inset-0 w-full h-full object-cover block scale-[1.01]" 
                          />
                        )}
                      </div>
                    );
                  })}
                </div>

                {getMediaList(selectedProject).length > 1 && (
                  <>
                    <button 
                      onClick={(e) => handlePrevMedia(e, getMediaList(selectedProject).length)}
                      className="absolute left-8 top-1/2 -translate-y-1/2 w-16 h-16 bg-black/40 hover:bg-white hover:text-black rounded-full flex items-center justify-center transition-all opacity-0 group-hover:opacity-100 backdrop-blur-md border border-white/5 shadow-2xl"
                    >
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                    <button 
                      onClick={(e) => handleNextMedia(e, getMediaList(selectedProject).length)}
                      className="absolute right-8 top-1/2 -translate-y-1/2 w-16 h-16 bg-black/40 hover:bg-white hover:text-black rounded-full flex items-center justify-center transition-all opacity-0 group-hover:opacity-100 backdrop-blur-md border border-white/5 shadow-2xl"
                    >
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                    </button>

                    <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-6 z-10 items-center">
                      {getMediaList(selectedProject).map((_, idx) => (
                        <button 
                          key={idx}
                          onClick={() => setCurrentMediaIndex(idx)}
                          className="group p-3"
                        >
                          <div className={`h-[3px] transition-all duration-1000 rounded-full ${idx === currentMediaIndex ? 'w-12 bg-white shadow-[0_0_15px_rgba(255,255,255,0.8)]' : 'w-4 bg-white/10 group-hover:bg-white/30'}`} />
                        </button>
                      ))}
                    </div>
                  </>
                )}
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-24 pb-12">
                <div className="lg:col-span-2 space-y-10">
                  <div className="space-y-6">
                    <h3 className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-700">{t.project.overview}</h3>
                    <p className="text-xl md:text-3xl text-zinc-300 leading-relaxed font-light italic">{selectedProject.description}</p>
                  </div>
