import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProjectCard from './components/ProjectCard';
import AIAssistant from './components/AIAssistant';
import { PROJECTS, SKILLS } from './constants';
import { Project } from './types';
import { translations } from './translations';

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
  const [activeFilter, setActiveFilter] = useState<'All' | 'Animation' | 'Lookdev' | 'Environment'>('All');
  const [hasKey, setHasKey] = useState<boolean | null>(null);

  const t = translations[lang];

  // Check for API Key on mount
  useEffect(() => {
    const checkKey = async () => {
      try {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      } catch (e) {
        setHasKey(false);
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (selectedProject) {
      document.body.classList.add('modal-open');
    } else {
      document.body.classList.remove('modal-open');
    }
    setCurrentMediaIndex(0);
  }, [selectedProject]);

  const handleOpenKeySelector = async () => {
    await window.aistudio.openSelectKey();
    setHasKey(true); // Assume success after interaction
  };

  const getMediaList = (project: Project) => {
    if (project.gallery && project.gallery.length > 0) return project.gallery;
    const list = [project.thumbnail];
    if (project.videoUrl) list.push(`VIDEO:${project.videoUrl}`);
    return list;
  };

  const handleNextMedia = (e?: React.MouseEvent, max?: number) => {
    if (e) e.stopPropagation();
    const limit = max || (selectedProject ? getMediaList(selectedProject).length : 0);
    if (limit > 1) {
      setCurrentMediaIndex((prev) => (prev + 1) % limit);
    }
  };

  const handlePrevMedia = (e: React.MouseEvent, max: number) => {
    e.stopPropagation();
    setCurrentMediaIndex((prev) => (prev - 1 + max) % max);
  };

  const filteredProjects = PROJECTS.filter(project => {
    if (activeFilter === 'All') return true;
    const cat = project.category.toLowerCase();
    if (activeFilter === 'Animation') return cat.includes('animación') || cat.includes('animation');
    if (activeFilter === 'Lookdev') return cat.includes('lookdev');
    if (activeFilter === 'Environment') return cat.includes('environment') || cat.includes('entorno') || cat.includes('ruins');
    return true;
  });

  // Loading state while checking key
  if (hasKey === null) {
    return <div className="min-h-screen bg-black flex items-center justify-center">
      <div className="w-12 h-12 border-t-2 border-white rounded-full animate-spin"></div>
    </div>;
  }

  // Mandatory Key Selection UI to fix "Refused Connection"
  if (hasKey === false) {
    return (
