                  className={`px-6 py-2 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border ${
                    activeFilter === filter ? 'bg-white text-black border-white' : 'bg-transparent text-zinc-600 border-zinc-900 hover:text-white'
