                <span className="text-zinc-600 text-[10px] font-black uppercase tracking-[0.5em]">{t.about.tagline}</span>
                <h2 className="text-5xl font-serif text-white tracking-tighter leading-none">{t.about.title1} <span className="italic text-zinc-500">{t.about.title2}</span></h2>
              </div>
              <p className="text-zinc-400 leading-relaxed text-xl font-light italic">{t.about.desc}</p>
              <div className="space-y-8">
                {SKILLS.map(skill => (
                  <div key={skill.name} className="space-y-3">
                    <div className="flex justify-between text-[10px] uppercase tracking-widest font-black text-zinc-500">
                      <span>{skill.icon} {skill.name}</span>
                      <span>{skill.level}%</span>
                    </div>
                    <div className="h-px w-full bg-zinc-900"><div className="h-full bg-white transition-all duration-1000" style={{ width: `${skill.level}%` }}></div></div>
                  </div>
                ))}
              </div>
            </div>
            <div className="relative aspect-[4/5] bg-zinc-900 rounded-sm overflow-hidden group">
              <img src="https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&q=80&w=1000" className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" alt="Matias CGI" />
            </div>
          </div>
        </section>

        {/* Sección CONTACTO */}
        <section id="contact" className="py-60 px-6 text-center bg-black scroll-mt-28">
          <div className="max-w-4xl mx-auto space-y-16">
            <h2 className="text-7xl md:text-9xl font-serif leading-none text-white tracking-tighter">{t.contact.title1} <br /> <span className="italic text-zinc-600">{t.contact.title2}</span></h2>
            <div className="flex flex-col items-center gap-8">
              <a href="mailto:hello@matias.cgi" className="text-3xl md:text-6xl font-bold tracking-tighter text-zinc-400 hover:text-white transition-colors border-b border-zinc-900 pb-4">hello@matias.cgi</a>
              <div className="flex gap-8 text-[10px] font-black uppercase tracking-[0.4em] text-zinc-600">
                <a href="#" className="hover:text-white">ArtStation</a>
                <a href="#" className="hover:text-white">LinkedIn</a>
                <a href="#" className="hover:text-white">Instagram</a>
              </div>
            </div>
          </div>
        </section>
      </main>

      {/* Footer Minimalista */}
      <footer className="py-12 border-t border-zinc-900 px-6 bg-black text-[9px] uppercase tracking-[0.5em] font-black text-zinc-800 text-center">
        © 2024 Matías Navarrete — {t.contact.footer}
      </footer>

      {/* Modal Refinado */}
      {selectedProject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl">
          <div className="relative max-w-6xl w-full bg-[#050505] border border-zinc-900 max-h-[90vh] overflow-y-auto rounded-sm">
            <button onClick={() => setSelectedProject(null)} className="absolute top-6 right-6 z-10 w-10 h-10 bg-white text-black rounded-full flex items-center justify-center font-bold hover:scale-110 transition-transform">✕</button>
            <div className="p-8 md:p-12 space-y-10">
              <div className="space-y-2">
                <span className="text-[10px] uppercase tracking-widest text-zinc-600 font-bold">{selectedProject.category} • {selectedProject.year}</span>
                <h2 className="text-3xl md:text-5xl font-serif text-white">{selectedProject.title}</h2>
              </div>
              <div className="aspect-video bg-black border border-zinc-800 rounded-sm overflow-hidden flex items-center justify-center">
                <img src={selectedProject.thumbnail} className="w-full h-full object-contain" alt="Project Preview" />
