import { GoogleGenAI } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

export const getAIResponse = async (userMessage: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  // Inicialización directa según guías actualizadas para asegurar el uso de la clave más reciente
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({ role: h.role, parts: h.parts })),
        { role: 'user', parts: [{ text: userMessage }] }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    return response.text || "I'm sorry, I couldn't process that request.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "The creative assistant is currently offline. Please try again later.";
  }
};

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProjectCard from './components/ProjectCard';
import AIAssistant from './components/AIAssistant';
import { PROJECTS, SKILLS } from './constants';
import { Project } from './types';
import { translations } from './translations';

// Removed redundant declaration of window.aistudio to avoid conflict with existing global types

const App: React.FC = () => {
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);
  const [activeFilter, setActiveFilter] = useState<'All' | 'Animation' | 'Lookdev' | 'Environment'>('All');
  const [hasKey, setHasKey] = useState<boolean | null>(null);

  const t = translations[lang];

  useEffect(() => {
    const checkKey = async () => {
      try {
        // Accessing aistudio from window using type casting as it is injected by the environment
        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
          const selected = await aistudio.hasSelectedApiKey();
          setHasKey(selected);
        } else {
          setHasKey(false);
        }
      } catch (e) {
        setHasKey(false);
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    if (selectedProject) {
      document.body.classList.add('modal-open');
    } else {
      document.body.classList.remove('modal-open');
    }
    setCurrentMediaIndex(0);
  }, [selectedProject]);

  const handleOpenKeySelector = async () => {
    try {
      const aistudio = (window as any).aistudio;
      if (aistudio && typeof aistudio.openSelectKey === 'function') {
        await aistudio.openSelectKey();
        // Assume key selection was successful after triggering the dialog to avoid race conditions
        setHasKey(true);
      }
    } catch (e) {
      console.error("Failed to open key selector", e);
    }
  };

  const getMediaList = (project: Project) => {
    if (project.gallery && project.gallery.length > 0) return project.gallery;
    const list = [project.thumbnail];
    if (project.videoUrl) list.push(`VIDEO:${project.videoUrl}`);
    return list;
  };

  const handleNextMedia = (e?: React.MouseEvent, max?: number) => {
    if (e) e.stopPropagation();
    const limit = max || (selectedProject ? getMediaList(selectedProject).length : 0);
    if (limit > 1) {
      setCurrentMediaIndex((prev) => (prev + 1) % limit);
